package assistant

import (
	"context"
	"html"
	"maps"
	"strings"
)

// An agyRelayContext is generated by this manager for one physical recipient and relay attempt.
// Its text is separate from the durable supervision message and never crosses a logical queue.
type agyRelayContextKey struct{}

type agyRelayContext struct {
	machine, session, onceID, block, plain string
}

func (a agyRelayContext) matches(machine, method string, p map[string]any) bool {
	return a.block != "" && method == DeviceAssistantSend && a.machine == machine && a.session == p["session_id"] && a.onceID == p["once_id"]
}

// Keep the ordinary, fully prepared request (including its provenance and other context) intact.
// Only the wire copy gets this attempt's diagnostic. A logical route can take the exact plain text
// for its own queue, without interpreting or removing anything from the message.
func agyRelayWireParams(ctx context.Context, machine, method string, params any) (context.Context, any) {
	if method != DeviceAssistantSend {
		return ctx, params
	}
	a, ok := ctx.Value(agyRelayContextKey{}).(agyRelayContext)
	p, isMap := params.(map[string]any)
	if !ok || !isMap || !a.matches(machine, method, p) {
		return ctx, params
	}
	a.plain, _ = p["text"].(string)
	wire := maps.Clone(p)
	wire["text"] = a.block + a.plain
	return context.WithValue(ctx, agyRelayContextKey{}, a), wire
}

// agyRelayBlock resolves candidate references for this recipient at delivery. The durable relay contains only
// the short judgment and pane references. relayWords ignores the context when confirming the ordinary text.
func (s *Service) agyRelayBlock(ctx context.Context, machine, to string, msg relayMsg) string {
	if msg.Tool != superviseTool || msg.Signals == "" {
		return ""
	}
	signals, _ := decodeDigestSignals(msg.Signals)
	var blocks strings.Builder
	for _, g := range signals {
		if len(g.Unlinked) == 0 || g.Kind != sigUnjudged && g.Kind != sigNeedsUserExternalInfo {
			continue
		}
		t, ok := s.todoNow(g.Todo)
		if !ok || !s.agyRelayRecipient(ctx, t, g, machine, to) {
			continue
		}
		detail := s.agyUnlinkedDetail(ctx, t, g.Unlinked, machine, to)
		if detail == "" || detail == g.Detail {
			continue
		}
		blocks.WriteString(`<persona-context kind="context" title="`)
		blocks.WriteString(html.EscapeString(g.Todo))
		blocks.WriteString("\">\n")
		// The ids are node-supplied. They must not be able to close the context block.
		blocks.WriteString(strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;").Replace(detail))
		blocks.WriteString("\n</persona-context>\n")
	}
	return blocks.String()
}

// agyRelayRecipient checks the current destination even if this relay was already in flight when a task moved.
func (s *Service) agyRelayRecipient(ctx context.Context, t Todo, g superviseSignal, machine, to string) bool {
	cfg := s.settings(ctx)
	if t.DoneAt != nil || !s.sameMachine(machine, s.conversationMachine(ctx, to, "")) {
		return false
	}
	if g.Kind == sigNeedsUserExternalInfo && !s.needsUserExternalInfoStillHolds(t, g) {
		return false
	}
	if s.agentSupervised(t) {
		if g.Kind != sigNeedsUserExternalInfo {
			return false // task leaders cannot inspect candidate conversations
		}
		up, _ := s.supervisorAboveTask(ctx, t)
		return up != "" && to == s.digestConversation(ctx, cfg, g, up)
	}
	g = s.currentSupervisorSignal(g)
	return to != "" && to == s.recheckDigestTarget(ctx, cfg, g)
}
